    if "LSQ" in queues:
        L.append('    LSQ [label="LSQ（LQ/SQ→L1D/TLB）· lsq_unit.cc:338"];')
    L.append('    ROB [label="ROB · rob.cc:194"];')
    for a, b in sorted(edges):
        style = ' [style=dashed, label="误预测恢复"]' if (a, b) == ("COMMIT", "REDIRECT") else ""
